import sys

# 计算并返回 floor(sqrt(x))
# 时间 O(log x)，空间 O(1)
def mysqrt(x: int) -> int:
    # 特判：0 和 1 直接返回
    if x < 2:
        return x

    l, r = 1, x // 2 + 1  # 对于 x>=2，答案不超过 x//2 + 1
    ans = 0

    while l <= r:
        mid = l + (r - l) // 2
        # 用除法避免 mid*mid 的溢出风险（Python 大整数安全，但保持同一思路）
        if mid <= x // mid:
            ans = mid      # 记录当前可行解
            l = mid + 1    # 右移，寻找更大可行值
        else:
            r = mid - 1    # 左移，缩小范围
    return ans

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    x = int(data)
    print(mysqrt(x))

if __name__ == "__main__":
    main()

